// Supabase Edge Function "notify-order"
// Wird vom Datenbank-Webhook bei INSERT in public.orders aufgerufen und
// schickt per Resend eine Mail mit der Bestellübersicht.
// Secrets (im Dashboard unter Edge Functions → Secrets):
//   RESEND_API_KEY   – Schlüssel von resend.com
//   MAIL_TO          – Empfänger, kommagetrennt (z. B. "antonia@example.ch")
//   MAIL_FROM        – Absender, z. B. "FCWB Bestellung <onboarding@resend.dev>"
//                      (eigene Domain nur nach Verifizierung bei Resend)

// Vereinswappen als eingebettete Anlage (Outlook blockiert externe Bilder)
const LOGO_B64 = "";

const STAGES = ["Bestellt", "Bestellt", "Geliefert", "Bedruckt", "Abholbereit", "Übergeben"];

function esc(s: unknown): string {
  return String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c] as string));
}
function chDate(iso: string): string {
  const p = String(iso || "").split("-");
  return p.length === 3 ? `${p[2]}.${p[1]}.${p[0]}` : iso;
}

Deno.serve(async (req) => {
  try {
    const payload = await req.json();
    // Webhook-Format: { type: "INSERT", table: "orders", record: { id, data, ... } }
    if (payload.table !== "orders" || !["INSERT", "UPDATE", "DELETE"].includes(payload.type)) {
      return new Response("ignored", { status: 200 });
    }
    const o = payload.type === "DELETE" ? payload.old_record?.data : payload.record?.data;
    if (!o || !Array.isArray(o.items)) return new Response("no data", { status: 200 });

    const to = (Deno.env.get("MAIL_TO") || "").split(",").map((s) => s.trim()).filter(Boolean);
    const gmailUser = Deno.env.get("GMAIL_USER");          // Absender-Gmail
    const gmailPass = Deno.env.get("GMAIL_APP_PASSWORD");  // 16-stelliges App-Passwort
    const from = gmailUser ? `FCWB Bestellung <${gmailUser}>` : (Deno.env.get("MAIL_FROM") || "FCWB Bestellung <onboarding@resend.dev>");
    const key = Deno.env.get("RESEND_API_KEY");
    if ((!key && !gmailUser) || !to.length) return new Response("mail not configured", { status: 200 });

    // Art der Mail bestimmen
    const minStage = (x: { items?: { stage?: number }[] }) => Math.min(...(x.items || []).map((i) => Number(i.stage) || 0));
    const keyOf = (i: Record<string, unknown>) => [i.art, i.name, i.size, i.player || "", i.druck || ""].join("|");
    let kind = "Neue Bestellung";
    let statusText = "Bestellt – beim Shop ausgelöst";
    let changes: { name: string; art: string; size: string; player: string; oldQty: number; newQty: number }[] = [];
    let shopMail = true; // Mails, die den Shop betreffen (Bestellung, Storno, Erhoehung, Loeschung)
    if (payload.type === "DELETE") {
      kind = "Stornierung – Bestellung gelöscht"; statusText = "storniert";
      changes = o.items.map((i: Record<string, unknown>) => ({ name: String(i.name), art: String(i.art), size: String(i.size), player: String(i.player || ""), oldQty: Number(i.qty) || 0, newQty: 0 }));
    } else if (payload.type === "UPDATE") {
      const prev = payload.old_record?.data;
      if (!prev) return new Response("no old data", { status: 200 });
      // Mengen-/Positionsaenderungen
      const oldMap = new Map<string, Record<string, unknown>>(); (prev.items || []).forEach((i: Record<string, unknown>) => oldMap.set(keyOf(i), i));
      const newMap = new Map<string, Record<string, unknown>>(); (o.items || []).forEach((i: Record<string, unknown>) => newMap.set(keyOf(i), i));
      for (const [k, i] of oldMap) { const n = newMap.get(k); const oq = Number(i.qty) || 0, nq = n ? Number(n.qty) || 0 : 0; if (oq !== nq) changes.push({ name: String(i.name), art: String(i.art), size: String(i.size), player: String(i.player || ""), oldQty: oq, newQty: nq }); }
      for (const [k, i] of newMap) { if (!oldMap.has(k)) changes.push({ name: String(i.name), art: String(i.art), size: String(i.size), player: String(i.player || ""), oldQty: 0, newQty: Number(i.qty) || 0 }); }
      if (changes.length) {
        const down = changes.some((c) => c.newQty < c.oldQty), up = changes.some((c) => c.newQty > c.oldQty);
        kind = down && up ? "Änderung der Bestellung" : down ? "Stornierung – Menge reduziert" : "Mengenerhöhung";
        statusText = STAGES[minStage(o)] ?? "";
      } else {
        const a = minStage(prev), b = minStage(o);
        const archNow = !!o.archived, archPrev = !!prev.archived;
        if (a === b && archNow === archPrev) return new Response("no relevant change", { status: 200 });
        kind = archNow && !archPrev ? "Bestellung abgeschlossen" : "Status geändert";
        statusText = archNow ? "Übergeben · im Archiv" : `${STAGES[a] ?? a} → ${STAGES[b] ?? b}`;
        shopMail = false;
      }
    }
    const total = o.items.reduce((a: number, b: { qty?: number }) => a + (Number(b.qty) || 0), 0);
    const subject = `FCWB ${kind}: ${chDate(o.date)} · ${o.besteller}${o.empfaenger ? " → " + o.empfaenger : ""} · ${statusText}`;
    const LOGO = "cid:fcwb-logo";
    const td = 'style="padding:7px 10px;border-bottom:1px solid #DCE6F1;font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#0F1E33;vertical-align:top"';
    const th = 'style="padding:8px 10px;background:#0B2A5B;color:#ffffff;font-family:Arial,Helvetica,sans-serif;font-size:12px;text-align:left"';
    const rowsHtml = o.items.map((it: Record<string, unknown>, i: number) => `
        <tr>
          <td ${td}>${i + 1}</td>
          <td ${td}><b>${esc(it.art)}</b></td>
          <td ${td}>${esc(it.name)}</td>
          <td ${td}>${esc(it.color)}</td>
          <td ${td}>${esc(it.line)}</td>
          <td ${td}>${esc(it.size)}</td>
          <td ${td.replace('vertical-align:top', 'vertical-align:top;text-align:right')}>${esc(it.qty)}</td>
          <td ${td}>${esc(it.druck)}</td>
          <td ${td}>${esc(it.player)}</td>
          <td ${td}>${esc(STAGES[Number(it.stage)] ?? "")}</td>
        </tr>`).join("");
    const meta = (k: string, v: string) => `<tr><td style="padding:3px 16px 3px 0;font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#5B6B7B">${k}</td><td style="padding:3px 0;font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#0F1E33"><b>${v}</b></td></tr>`;
    const html = `<!doctype html><html><body style="margin:0;padding:0;background:#EEF3FA">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF3FA;padding:24px 0">
  <tr><td align="center">
    <table role="presentation" width="820" cellpadding="0" cellspacing="0" style="max-width:820px;width:100%;background:#ffffff;border:1px solid #DCE6F1">
      <tr>
        <td style="background:#0B2A5B;padding:18px 24px">
          <table role="presentation" cellpadding="0" cellspacing="0"><tr>
            <td style="padding-right:16px"><img src="${LOGO}" width="64" height="76" alt="FC Weinfelden-Bürglen" style="display:block;border:0"></td>
            <td style="font-family:Arial,Helvetica,sans-serif;color:#ffffff">
              <div style="font-size:22px;font-weight:bold;letter-spacing:.3px">FC Weinfelden-Bürglen · Materialbestellung</div>
              <div style="font-size:13px;color:#FFC300;font-weight:bold;margin-top:4px">${esc(kind)} · ${esc(statusText)}</div>
            </td>
          </tr></table>
        </td>
      </tr>
      <tr><td style="padding:20px 24px 8px">
        <table role="presentation" cellpadding="0" cellspacing="0">
          ${meta("Besteller", esc(o.besteller))}
          ${meta("Bestelldatum", esc(chDate(o.date)))}
          ${meta("Lieferung an", esc(o.empfaenger || "—"))}
          ${o.note ? meta("Notiz", esc(o.note)) : ""}
          ${meta("Positionen", total + " Stück")}
        </table>
      </td></tr>
      ${changes.length ? `<tr><td style="padding:0 24px 12px">
        <div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:bold;color:#C0392B;margin-bottom:6px">${esc(kind)}</div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">
          <tr><th ${th}>Art.-Nr.</th><th ${th}>Artikel</th><th ${th}>Grösse</th><th ${th}>Spieler</th><th ${th.replace('text-align:left', 'text-align:right')}>bisher</th><th ${th.replace('text-align:left', 'text-align:right')}>neu</th><th ${th.replace('text-align:left', 'text-align:right')}>Differenz</th></tr>
          ${changes.map((c) => `<tr><td ${td}><b>${esc(c.art)}</b></td><td ${td}>${esc(c.name)}</td><td ${td}>${esc(c.size)}</td><td ${td}>${esc(c.player)}</td><td ${td.replace('vertical-align:top', 'vertical-align:top;text-align:right')}>${c.oldQty}</td><td ${td.replace('vertical-align:top', 'vertical-align:top;text-align:right')}>${c.newQty}</td><td ${td.replace('vertical-align:top', 'vertical-align:top;text-align:right;font-weight:bold;color:' + (c.newQty < c.oldQty ? '#C0392B' : '#1E8E3E'))}>${c.newQty - c.oldQty > 0 ? '+' : ''}${c.newQty - c.oldQty}</td></tr>`).join("")}
        </table>
        <div style="font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#5B6B7B;margin-top:8px">Unten der aktuelle Stand der gesamten Bestellung${payload.type === "DELETE" ? " vor der Löschung" : ""}.</div>
      </td></tr>` : ""}
      ${changes.length ? `<tr><td style="padding:0 24px 12px"><div style="background:#FFF6D6;border:1px solid #FFC300;padding:10px 14px;font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#0F1E33"><b>Bitte zusätzlich telefonisch bei 11teamsports melden: 044 362 05 55</b></div></td></tr>` : ""}
      <tr><td style="padding:8px 24px 20px">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">
          <tr>
            <th ${th}>#</th><th ${th}>Art.-Nr.</th><th ${th}>Artikel</th><th ${th}>Farbe</th><th ${th}>Linie</th>
            <th ${th}>Grösse</th><th ${th.replace('text-align:left', 'text-align:right')}>Menge</th><th ${th}>Bedruckung</th><th ${th}>Spieler</th><th ${th}>Status</th>
          </tr>
          ${rowsHtml}
          <tr>
            <td colspan="6" style="padding:8px 10px;font-family:Arial,Helvetica,sans-serif;font-size:13px;font-weight:bold;border-top:2px solid #0B2A5B">Total</td>
            <td style="padding:8px 10px;font-family:Arial,Helvetica,sans-serif;font-size:13px;font-weight:bold;text-align:right;border-top:2px solid #0B2A5B">${total}</td>
            <td colspan="3" style="border-top:2px solid #0B2A5B"></td>
          </tr>
        </table>
      </td></tr>
      <tr><td style="padding:0 24px 22px">
        <table role="presentation" cellpadding="0" cellspacing="0"><tr>
          <td style="background:#FFC300;padding:11px 18px"><a href="https://99antonia2599.github.io/fcwb-bestellung/" style="font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:bold;color:#0B2A5B;text-decoration:none">Zur Verfolgung öffnen</a></td>
        </tr></table>
        <div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#5B6B7B;margin-top:14px">Automatische Nachricht der FCWB Materialbestellung.</div>
      </td></tr>
    </table>
  </td></tr>
</table>
</body></html>`;

    // Weg 1: Gmail per SMTP (an beliebige Empfänger), wenn eingerichtet
    if (gmailUser && gmailPass) {
      const nodemailer = (await import("npm:nodemailer@6.9.13")).default;
      const transporter = nodemailer.createTransport({ host: "smtp.gmail.com", port: 465, secure: true, auth: { user: gmailUser, pass: gmailPass } });
      const info = await transporter.sendMail({ from, to, subject, html,
        attachments: [{ filename: "fcwb-logo.png", content: LOGO_B64, encoding: "base64", contentType: "image/png", cid: "fcwb-logo" }] });
      return new Response(JSON.stringify({ via: "gmail", id: info.messageId }), { status: 200 });
    }
    // Weg 2: Resend (nur an die Konto-Adresse, solange keine Domain verifiziert ist)
    const r = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({ from, to, subject, html, attachments: [{ filename: "fcwb-logo.png", content: LOGO_B64, content_type: "image/png", content_id: "fcwb-logo" }] }),
    });
    const body = await r.text();
    return new Response(body, { status: r.ok ? 200 : 500 });
  } catch (e) {
    return new Response("error: " + (e as Error).message, { status: 500 });
  }
});
